SOURCE_CLAIM_JSON: {"title":"High Level Meeting to Commemorate and Promote the International Day for the Total Elimination of Nuclear Weapons | Philippines","publisher":"Permanent Mission of the Republic of the Philippines to the United Nations","publication_date":"2022-09-26","url":"https://www.un.int/philippines/statements_speeches/high-level-meeting-commemorate-and-promote-international-day-total-elimination","claim":"The Philippine delegation said President Marcos had told the General Assembly to reject deterrence and stay committed to decreasing the global nuclear stockpile, while warning that nuclear weapons plus emerging technologies could bring humanity closer to extinction.","locator":"lines 41-47","source_type":"official","source_confidence":"high","source_confidence_reason":"Dated UN statement explicitly attributes the earlier presidential remark.","final_evidence_use":"final_evidence","period_fit":"Directly within 2022.","ruler_attribution":"The statement explicitly attributes the deterrence line to President Marcos.","contrary_evidence":["This is a public normative statement, not evidence of command-and-control or a concrete nuclear-security reform."],"lenses":["1B.1","1B.2","1B.4","1B.8","1B.9","1B.10"]}
